## Implementation

```typescript
// src/provider/factory.ts

import { Provider, ProviderConfig } from './types';
import { CodespacesProvider } from './providers/codespaces';
import { CoderProvider } from './providers/coder';

export function createProvider(config: ProviderConfig): Provider {
  switch (config.type) {
    case 'codespaces':
      return new CodespacesProvider();
    case 'coder':
      if (!config.authToken || !config.url) {
        throw new Error('Coder provider requires authToken and url');
      }
      return new CoderProvider(config.url, config.authToken);
    default:
      throw new Error(`Unknown provider type: ${(config as any).type}`);
  }
}
```

